// AreKRM validates if given resources are valid KRM resources.
func AreKRM(nodes []*yaml.RNode) error {
	for i := range nodes {
		if err := IsKRM(nodes[i]); err != nil {
			path, _, _ := kioutil.GetFileAnnotations(nodes[i])
			return fmt.Errorf("%s: %w", path, err)
		}
	}
	return nil
}

// MergeWithInput merges the transformed output with input resources
// input: all input resources, selectedInput: selected input resources
// output: output resources as the result of function on selectedInput resources
// for input: A,B,C,D; selectedInput: A,B; output: A,E(A transformed, B Deleted, E Added)
// the result should be A,C,D,E
// resources are identified by kpt-resource-id annotation
func MergeWithInput(output, selectedInput, input []*yaml.RNode) []*yaml.RNode {
	var result []*yaml.RNode
	for i := range input {
		presentInSelectedInput := presentIn(input[i], selectedInput)
		presentInOutput := presentIn(input[i], output)
		if !presentInSelectedInput {
			// this resource is untouched
			result = append(result, input[i])
			continue
		}

		if presentInOutput {
			// this resource modified by function, so replace it from the output
			result = append(result, nodeWithResourceID(input[i].GetAnnotations()[ResourceIDAnnotation], output))
		}
		// if presentInSelectedInput and !presentInOutput the resource is deleted, so ignore it
	}

	// add function generated resources to the result
	for i := range output {
		if output[i].GetAnnotations()[ResourceIDAnnotation] == "" {
			result = append(result, output[i])
		}
	}

	return result
}

// SetResourceIDs adds kpt-resource-id annotation to each input resource
func SetResourceIDs(input []*yaml.RNode) error {
	id := 0
	for i := range input {
		idStr := fmt.Sprintf("%v", id)
		err := input[i].PipeE(yaml.SetAnnotation(ResourceIDAnnotation, idStr))
		if err != nil {
			return err
		}
		id++
	}
	return nil
}

// DeleteResourceIDs removes the kpt-resource-id annotation from all resources
func DeleteResourceIDs(input []*yaml.RNode) error {
	for i := range input {
		err := input[i].PipeE(yaml.ClearAnnotation(ResourceIDAnnotation))
		if err != nil {
			return err
		}
	}
	return nil
}

// SelectInput returns the selected resources based on criteria in selectors
func SelectInput(input []*yaml.RNode, selectors, exclusions []kptfilev1.Selector, _ *SelectionContext) ([]*yaml.RNode, error) {
	var selectedInput []*yaml.RNode
	if len(selectors) == 0 {
		selectedInput = input
	} else {
		for _, node := range input {
			for _, selector := range selectors {
				if IsMatch(node, selector) {
					selectedInput = append(selectedInput, node)
				}
			}
		}
	}
	if len(exclusions) == 0 {
		return selectedInput, nil
	}
	var filteredInput []*yaml.RNode
	for _, node := range selectedInput {
		matchesExclusion := false
		for _, exclusion := range exclusions {
			if !exclusion.IsEmpty() && IsMatch(node, exclusion) {
				matchesExclusion = true
				break
			}
		}
		if !matchesExclusion {
			filteredInput = append(filteredInput, node)
		}
	}
	return filteredInput, nil
}

func E(args ...any) error {
	if len(args) == 0 {
		panic("errors.E must have at least one argument")
	}

	e := &Error{}
	for _, arg := range args {
		switch a := arg.(type) {
		case kptfilev1.UniquePath:
			e.Path = a
		case Op:
			e.Op = a
		case Fn:
			e.Fn = a
		case Repo:
			e.Repo = a
		case Class:
			e.Class = a
		case *Error:
			e.Err = new(*a)
		case error:
			e.Err = a
		case string:
			e.Err = fmt.Errorf("%s", a)
		default:
			panic(fmt.Errorf("unknown type %T for value %v in call to error.E", a, a))
		}
	}
	wrappedErr, ok := e.Err.(*Error)
	if !ok {
		return e
	}
	if e.Path == wrappedErr.Path {
		wrappedErr.Path = ""
	}

	if e.Op == wrappedErr.Op {
		wrappedErr.Op = ""
	}

	if e.Fn == wrappedErr.Fn {
		wrappedErr.Fn = ""
	}

	if e.Repo == wrappedErr.Repo {
		wrappedErr.Repo = ""
	}

	if e.Class == wrappedErr.Class {
		wrappedErr.Class = 0
	}
	return e
}

// Pipeline returns the Pipeline section of the pkg's Kptfile.
// if pipeline is not specified in a Kptfile, it returns Zero value of the pipeline.
func (p *Pkg) Pipeline() (*kptfilev1.Pipeline, error) {
	kf, err := p.Kptfile()
	if err != nil {
		return nil, err
	}
	pl := kf.Pipeline
	if pl == nil {
		return &kptfilev1.Pipeline{}, nil
	}
	return pl, nil
}

// Validates the package pipeline.
func (p *Pkg) ValidatePipeline() error {
	pl, err := p.Pipeline()
	if err != nil {
		return err
	}

	if pl.IsEmpty() {
		return nil
	}

	// read all resources including function pipeline.
	resources, err := p.LocalResources()
	if err != nil {
		return err
	}

	resourcesByPath := sets.String{}

	// TODO: should we use go.uber.org/multierr instead?
	var errs []error
	for _, r := range resources {
		rPath, _, err := kioutil.GetFileAnnotations(r)
		if err != nil {
			errs = append(errs, fmt.Errorf("resource %q missing path annotation err: %w", r.GetName(), err))
		}
		resourcesByPath.Insert(filepath.Clean(rPath))
	}

	if len(errs) > 0 {
		return stderrors.Join(errs...)
	}

	for i, fn := range pl.Mutators {
		if fn.ConfigPath != "" && !resourcesByPath.Has(filepath.Clean(fn.ConfigPath)) {
			errs = append(errs, makeStepValidationErr("mutator", i, fn.Name, fn.Image, fn.ConfigPath))
		}
	}
	for i, fn := range pl.Validators {
		if fn.ConfigPath != "" && !resourcesByPath.Has(filepath.Clean(fn.ConfigPath)) {
			errs = append(errs, makeStepValidationErr("validator", i, fn.Name, fn.Image, fn.ConfigPath))
		}
	}
	return stderrors.Join(errs...)
}
